def fewest_hops(stones, lo, hi):
    n = len(stones)
    best = [-1] * n
    best[0] = 0
    for j in range(1, n):
        if stones[j] != '.':
            continue
        options = [best[i] for i in range(max(0, j - hi), j - lo + 1) if best[i] >= 0]
        if options:
            best[j] = min(options) + 1
    return best[n - 1]
